// Bind into <input> elements as the value — that's probably the only use case so far.
import { getValueFromBrowserStorage, getValueFromSource } from './get-value.js'

import { isEmpty } from '@splendidlabz/utils'

export function populate(node, options) {
  const { prop = '', fallback = '', source = {} } = options
  const list = prop.split('.')
  let value

  if (!isEmpty(source)) value = getValueFromSource({ source, list }) || fallback
  if (isEmpty(source)) value = getValueFromBrowserStorage(list) || fallback

  node.value = value
}

export function conditionalPopulate(node, options) {
  const { prop = '', conditions = { fallback: '' }, source = {} } = options
  const list = prop.split('.')
  let value

  if (!isEmpty(source)) {
    const tmp = getValueFromSource({ source, list })
    value = conditions[tmp] || conditions.fallback
  }
  if (isEmpty(source)) {
    const tmp = getValueFromBrowserStorage(list)
    value = conditions[tmp] || conditions.fallback
  }

  node.value = value
}
